<?php require __DIR__.'/config/config.php'; ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track orders | KigoTech</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="top"><a class="brand" href="index.php">KigoTech <span>Online Market</span></a><a href="index.php">Continue shopping</a></header><main><p class="eyebrow">ORDER HISTORY</p><h1>Track your orders</h1><div id="orders">Loading your orders...</div></main><script>
async function load(){let r=await fetch('api/index.php?action=my_orders',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});let d=await r.json();if(!r.ok){document.querySelector('#orders').innerHTML='Please sign in on the shop page first.';return}document.querySelector('#orders').innerHTML=d.orders.map(o=>`<article class="card" style="margin:15px 0"><h3>${o.order_number}</h3><p><b>${o.status}</b> · ${new Date(o.created_at).toLocaleString()}</p><p>Total: KSh ${Number(o.total).toLocaleString()}</p>${o.items.map(i=>`<p>${i.product_name} × ${i.quantity}</p>`).join('')}<small>Last update: ${o.updated_at}</small></article>`).join('')||'No orders yet.'}load();</script></body></html>
